content.content:
1	import { z } from "zod";
2	
3	// Location resolution — pure. No I/O, no clock.
4	// We NEVER derive a city name from coordinates: Open-Meteo has no reverse endpoint
5	// (D8), and third-party reverse geocoders would ship precise user coords off-stack.
6	
7	/** What we persist to profiles.location_source. */
8	export type LocationSource = "geo" | "city";
9	/** Where the location we're using actually came from. */
10	export type LocationOrigin = LocationSource | "profile" | "default";
11	
12	export type ResolvedLocation = {
13	  lat: number;
14	  lon: number;
15	  label: string;
16	  origin: LocationOrigin;
17	};
18	
19	export type ProfileLocation = {
20	  location_lat: number | null;
21	  location_lon: number | null;
22	  location_label: string | null;
23	  /** 'city' means the user deliberately picked it — GPS must not silently override it. */
24	  location_source?: string | null;
25	};
26	
27	export const DEFAULT_LOCATION: ResolvedLocation = {
28	  lat: 52.52,
29	  lon: 13.41,
30	  label: "Berlin",
31	  origin: "default",
32	};
33	
34	/**
35	 * 2dp ≈ 1.1km. Raw GPS precision would make every user's forecast URL unique,
36	 * defeating the 30-minute fetch cache in fetchForecast and burning the
37	 * Open-Meteo daily request budget. Also stores less precise personal data.
38	 */
39	export function roundCoord(n: number): number {
40	  return Math.round(n * 100) / 100;
41	}
42	
43	export function resolveLocation(args: {
44	  input?: { lat: number; lon: number; label: string; source: LocationSource };
45	  profile?: ProfileLocation | null;
46	}): ResolvedLocation {
47	  const { input, profile } = args;
48	
49	  if (input) {
50	    return { lat: input.lat, lon: input.lon, label: input.label, origin: input.source };
51	  }
52	
53	  if (profile?.location_lat != null && profile.location_lon != null) {
54	    // Surface the STORED provenance, not a flat "profile": the client uses
55	    // origin === "city" to know a deliberate choice is in play and suppress the
56	    // silent GPS refresh that would otherwise overwrite it.
57	    const stored = profile.location_source;
58	    return {
59	      lat: profile.location_lat,
60	      lon: profile.location_lon,
61	      label: profile.location_label ?? "Current location",
62	      origin: stored === "city" || stored === "geo" ? stored : "profile",
63	    };
64	  }
65	
66	  return { ...DEFAULT_LOCATION };
67	}
68	
69	/**
70	 * The columns a location write sets, shared by both write paths.
71	 *
72	 * `saveLocation` (the Stylist, which already knows the timezone from the
73	 * generate that just ran) and `setLocation` (Settings, which has to resolve one)
74	 * must write identical shapes — a column set that drifts between them is how the
75	 * two screens start disagreeing about where you are.
76	 *
77	 * Pure, and takes `nowIso` rather than reading the clock, so it can be tested.
78	 */
79	export function locationColumns(d: LocationInput, nowIso: string) {
80	  return {
81	    location_lat: roundCoord(d.lat),
82	    location_lon: roundCoord(d.lon),
83	    location_label: d.label,
84	    location_source: d.source,
85	    location_timezone: d.timezone,
86	    location_updated_at: nowIso,
87	  };
88	}
89	
90	/** Great-circle distance in kilometres. */
91	export function distanceKm(
92	  a: { lat: number; lon: number },
93	  b: { lat: number; lon: number },
94	): number {
95	  const R = 6371;
96	  const rad = (d: number) => (d * Math.PI) / 180;
97	  const dLat = rad(b.lat - a.lat);
98	  const dLon = rad(b.lon - a.lon);
99	  const h =
100	    Math.sin(dLat / 2) ** 2 +
101	    Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
102	  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
103	}
104	
105	/**
106	 * How far the user must move before today's looks are wrong.
107	 *
108	 * This is a WEATHER threshold, not a precision one. Below ~25km the forecast is
109	 * effectively identical, so the stored looks are still right for the conditions
110	 * they were composed for, and throwing them away would spend a model call to
111	 * produce the same answer.
112	 *
113	 * It has to be this coarse because the Stylist's silent GPS refresh runs on
114	 * every load: at a tighter threshold, anyone who commutes would pay for a fresh
115	 * generation every morning.
116	 */
117	export const STALE_LOCATION_KM = 25;
118	
119	/**
120	 * Has the user moved far enough that today's stored drop no longer describes
121	 * where they are?
122	 *
123	 * `previous` is the RESOLVED location the looks were built for — pass
124	 * `resolveLocation({ profile })`, not the raw columns. A profile with no
125	 * location still generated its drop against `DEFAULT_LOCATION`, so comparing
126	 * against a null column would miss the very first move a user makes.
127	 */
128	export function locationMoved(
129	  next: { lat: number; lon: number },
130	  previous: { lat: number; lon: number },
131	  minKm: number = STALE_LOCATION_KM,
132	): boolean {
133	  return distanceKm(next, previous) > minKm;
134	}
135	
136	/**
137	 * What the client may persist. Plain Zod validation keywords are fine here —
138	 * this schema is NEVER sent to Anthropic as a structured-output format, so the
139	 * `forStructuredOutput()` stripping rule does not apply.
140	 */
141	export const LocationInputSchema = z.object({
142	  lat: z.number().min(-90).max(90),
