1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { readPreferences } from "@/lib/profile/preferences";
8	import { personalBand, applyFormalityOverride } from "@/lib/generator/rules";
9	import { buildCandidates, missingCategory, type CandidateItem } from "@/lib/generator/candidates";
10	import { rankTopN } from "@/lib/generator/rank";
11	import { diversify } from "@/lib/generator/diversity";
12	import { currentSeason } from "@/lib/generator/season";
13	import { rerank, MAX_PICKS } from "@/lib/generator/rerank";
14	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
15	import { localDateFor } from "@/lib/outfits/local-date";
16	import { loadDailyLooks, saveDailyLooks } from "@/lib/outfits/daily";
17	import { reassembleLooks } from "@/lib/outfits/reassemble";
18	import {
19	  assertCanGenerate,
20	  noteGeneration,
21	  QuotaExceededError,
22	  type GenerationRequest,
23	} from "@/lib/outfits/quota";
24	import { predictOccasion, defaultReason } from "@/lib/outfits/predict-occasion";
25	import { recordOverride } from "@/lib/outfits/overrides";
26	import {
27	  resolveLocation,
28	  roundCoord,
29	  locationColumns,
30	  locationMoved,
31	  LocationInputSchema,
32	  type LocationSource,
33	} from "@/lib/weather/location";
34	import type {
35	  GenerateResult,
36	  Look,
37	  LookDraft,
38	  LookPiece,
39	  UiOccasion,
40	  WeatherPayload,
41	} from "@/lib/generator/types";
42	
43	export async function generate(input: {
44	  occasion: UiOccasion;
45	  formality: number | null;
46	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
47	  lean: string[];
48	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
49	  regenerate?: boolean;
50	  city?: { lat: number; lon: number; label: string; source: LocationSource };
51	}): Promise<GenerateResult> {
52	  try {
53	    const supabase = await createClient();
54	    const {
55	      data: { user },
56	    } = await supabase.auth.getUser();
57	    if (!user) return { status: "error", message: "Not signed in" };
58	
59	    const { data: profile } = await supabase
60	      .from("profiles")
61	      .select(
62	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
63	      )
64	      .eq("id", user.id)
65	      .single();
66	    const { data: itemsRaw } = await supabase
67	      .from("items")
68	      .select("*")
69	      .eq("user_id", user.id)
70	      .eq("archived", false);
71	    const items = itemsRaw ?? [];
72	    const byId = new Map(items.map((i) => [i.id, i]));
73	    const pathFor = (id: string) => {
74	      const it = byId.get(id);
75	      return it ? displayPath(it) : undefined;
76	    };
77	
78	    const loc = resolveLocation({ input: input.city, profile });
79	
80	    const now = new Date();
81	    const f = await fetchForecast(loc.lat, loc.lon);
82	    const prefs = readPreferences(profile?.preferences);
83	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
84	    const weather: WeatherPayload = {
85	      tempC: f.tempC,
86	      feelsLikeC: f.feelsLikeC,
87	      condition: f.condition,
88	      cityLabel: loc.label,
89	      timezone: f.timezone,
90	      locationOrigin: loc.origin,
91	      laterSentence: advice.sentence,
92	      adviceClause: advice.adviceClause,
93	      laterLabel: "Later",
94	      hourly: f.hourly,
95	      tempUnit: prefs.tempUnit,
96	    };
97	
98	    const today = localDateFor(now, f.timezone);
99	
100	    // The daily drop (Decision 5): today's looks are generated once and then
101	    // read back. Only an explicit regenerate spends an AI call on a day the
102	    // stylist has already answered.
103	    //
104	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
105	    // on a regenerate it is the recency signal — the pieces the user just
106	    // rejected, which ranking will sink without ever filtering them out.
107	    const stored = await loadDailyLooks(user.id, input.occasion, today);
108	
109	    /**
110	     * Today's looks were composed for wherever the user was when they were
111	     * generated. Moving invalidates them: Decision 5 caches the drop, but
112	     * caching does not make a 26°C Manila outfit correct under a 12°C
113	     * Reykjavik sky.
114	     *
115	     * Compared against the RESOLVED previous location, so the first move a
116	     * user makes — away from DEFAULT_LOCATION, with nothing stored yet — counts.
117	     *
118	     * Falling through here is deliberately how this is implemented: the block
119	     * below already records a fall-through as a `drop`, never a `regenerate`,
120	     * so the rebuild is free on every tier. The user changed where they are;
121	     * they did not ask for another look.
122	     *
123	     * The Settings path clears the stored rows outright in `setLocation`. This
124	     * covers the OTHER door — the Stylist's weather pill, which writes through
125	     * `saveLocation` AFTER this action has already run, and so cannot clear
126	     * anything without deleting the looks this very call just stored.
127	     */
128	    const movedAway = input.city
129	      ? locationMoved(input.city, resolveLocation({ profile }))
130	      : false;
131	
132	    if (!input.regenerate && !movedAway && stored?.length) {
133	      const paths = Array.from(
134	        new Set(
135	          stored
136	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
137	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
138	            .map((it) => displayPath(it)),
139	        ),
140	      );
141	      const signed = await signItemImages(paths);
142	      const looks = reassembleLooks(stored, byId, signed, pathFor);
143	      // null = the closet changed under the stored set; fall through and
144	      // regenerate rather than showing an outfit with a hole in it.
145	      if (looks) return { status: "ok", weather, looks };
146	    }
147	
148	    // Only a deliberate regenerate carries the signal. A fall-through from a
149	    // stale stored set is the app fixing itself, not the user asking for
150	    // something else — penalising those pieces would be arbitrary.
151	    const recentlyShown = input.regenerate
152	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
153	      : [];
154	
155	    /**
156	     * A fall-through is a DROP, not a regenerate.
157	     *
158	     * Reaching here without `input.regenerate` means either the occasion has no
159	     * looks today, or the stored set no longer reassembles because the closet
160	     * changed under it. Both are the app answering for the first time or
161	     * repairing its own bookkeeping — not the user asking again — and neither
162	     * should be charged. Drops are free on every tier regardless, so the
163	     * distinction only matters for what the ledger records.
164	     */
165	    const gen: GenerationRequest = {
166	      kind: input.regenerate ? "regenerate" : "drop",
167	      occasion: input.occasion,
168	      today,
169	    };
170	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
171	    // in scope so the screen keeps its strip instead of collapsing, and being
172	    // limited is a STATE, not a failure — routing it through the error path
173	    // would render "Couldn't reach the stylist" for a working app.
174	    try {
175	      await assertCanGenerate(user.id, gen);
176	    } catch (e) {
177	      if (e instanceof QuotaExceededError) {
178	        return { status: "limited", weather, message: e.message };
179	      }
180	      throw e;
181	    }
182	
183	    const candItems: CandidateItem[] = items.map((i) => ({
184	      id: i.id,
185	      category: i.category,
186	      colors: i.colors ?? [],
187	      formality: i.formality,
188	      seasons: i.seasons ?? [],
189	      material: i.material,
190	    }));
191	    // Occasion gives the context; the user's onboarding dress codes narrow it;
192	    // an explicit Refine formality overrides both.
193	    const band = applyFormalityOverride(
194	      personalBand(input.occasion, profile),
195	      input.formality,
196	    );
197	    const candidateArgs = {
198	      band,
199	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
200	      season: currentSeason(now),
201	      excludeItemIds: [],
202	      maxAccessories: 1,
203	      rainGuard: prefs.rainGuard,
204	    };
205	    const combos = buildCandidates(candItems, candidateArgs);
206	    if (combos.length === 0) {
207	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
208	    }
209	
210	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
211	    // The Refine colour pick lands here, in ranking — not in candidate building.
212	    // It reorders the shortlist toward the requested families and is dropped
213	    // silently when the closet cannot honour it.
214	    //
215	    // Rank everything, then spread the shortlist across the wardrobe before the
216	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
217	    // top harmonises with everything, so it occupies most of the list, and "the
218	    // best 3" of a clustered list is three versions of one outfit. Diversifying
219	    // the INPUT makes the model's three distinct by construction.
220	    // Season rides along as a ranking preference — in-season combos float to the
221	    // top of the shortlist the re-ranker sees, but an off-season one is still
222	    // offered rather than the screen going empty.
223	    const ranked = rankTopN(
224	      combos,
225	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
226	      combos.length,
227	    );
228	    const top = diversify(ranked, 20);
229	
230	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
231	    // in place, so it has to survive in what we hand back to the screen too —
232	    // otherwise the day's set silently loses it until the next page load. It
233	    // also still COUNTS toward the day's three, so the stylist is asked for
234	    // fewer fresh looks rather than the set growing a fourth tab.
235	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
236	
237	    const { picks } = await rerank({
238	      want: MAX_PICKS - pinnedStored.length,
239	      combos: top.map((t) =>
240	        t.items.map((ci) => {
241	          const it = byId.get(ci.id)!;
242	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
243	        }),
244	      ),
245	      aesthetic,
246	      occasion: input.occasion,
247	      weatherLabel: f.condition,
248	      tempC: f.tempC,
249	    });
250	
251	    const paths = Array.from(
252	      new Set([
253	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
254	        ...pinnedStored.flatMap((s) =>
255	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
256	        ),
257	      ]),
258	    );
259	    const signed = await signItemImages(paths);
260	
261	    // `rerank` already dropped picks that repeat a combo or point outside the
262	    // shortlist, so every index here resolves. It previously fell back to
263	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
264	    // of the first look rather than into one fewer look.
265	    const drafts: LookDraft[] = picks.map((p) => {
266	      const combo = top[p.combo_index].items;
267	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
268	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
269	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
270	        itemId: d.id,
271	        category: d.category,
272	        subcategory: d.subcategory ?? null,
273	        brand: d.brand ?? null,
274	        name: d.name ?? null,
275	        colors: d.colors ?? [],
276	        cutoutUrl: signed.get(displayPath(d)) ?? "",
277	        slot: slots[idx],
278	      }));
279	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
280	    });
281	
282	    // Fire-and-forget would be simpler, but a failed write means the user pays
283	    // for another AI call on their next tap — worth awaiting. The insert also
284	    // hands back the row ids, which are the detail screen's address.
285	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
286	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
287	
288	    // Recorded only now — after the model answered and the write succeeded. A
289	    // generation that failed cost the user nothing, so metering it would be
290	    // charging them for our error.
291	    await noteGeneration(user.id, gen);
292	
293	    // Pinned looks keep their place at the front — they hold the lower
294	    // look_index values, which is the order the next load will read them back in.
295	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
296	
297	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
298	  } catch (e) {
299	    console.error("[generate] failed:", e);
300	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
301	  }
302	}
303	
304	/**
305	 * The single write path for a user's location. `generate` stays read-only.
306	 * Called by the client after a successful generate for a location the user
307	 * actually supplied (geolocation or city search) — never for the profile or
308	 * default fallback, where there is nothing new to write.
309	 */
310	export async function saveLocation(input: unknown): Promise<void> {
311	  const d = LocationInputSchema.parse(input);
312	
313	  const supabase = await createClient();
314	  const {
315	    data: { user },
316	  } = await supabase.auth.getUser();
317	  if (!user) return;
318	
319	  await supabase
320	    .from("profiles")
321	    .update(locationColumns(d, new Date().toISOString()))
322	    .eq("id", user.id);
323	}
324	
325	/**
326	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
327	 * AI and NO weather — so the client can pick the right occasion before the first
328	 * generate without adding latency.
329	 */
330	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
331	  const supabase = await createClient();
332	  const {
333	    data: { user },
334	  } = await supabase.auth.getUser();
335	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
336	
337	  const { data: profile } = await supabase
338	    .from("profiles")
339	    .select("occasions, location_timezone")
340	    .eq("id", user.id)
341	    .single();
342	
343	  const tz = profile?.location_timezone ?? "UTC";
344	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
345	  return { occasion, reason: defaultReason(occasion) };
346	}
347	
348	/**
349	 * Record that the user chose an occasion other than the predicted default.
350	 * Fire-and-forget: the caller does not await the outcome, and a failure here
351	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
352	 * not logged as an override.
353	 */
354	export async function logOccasionOverride(input: {
355	  predicted: UiOccasion;
356	  chosen: UiOccasion;
357	}): Promise<void> {
358	  if (input.chosen === input.predicted) return;
359	
360	  const supabase = await createClient();
361	  const {
362	    data: { user },
363	  } = await supabase.auth.getUser();
364	  if (!user) return;
365	
366	  const { data: profile } = await supabase
367	    .from("profiles")
368	    .select("location_timezone")
369	    .eq("id", user.id)
370	    .single();
371	
372	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
373	  await recordOverride(user.id, today, input.predicted, input.chosen);
374	}
375

