110	    .from("outfits")
111	    .insert(rows)
112	    .select("id, look_index");
113	  if (!inserted) return [];
114	
115	  // outfit_items is the relational record — it is what wear_logs and future
116	  // analytics join against. The renderable geometry lives in outfits.layout.
117	  const links = inserted.flatMap((row) => {
118	    const look = looks[row.look_index - start];
