124	  });
125	  if (links.length) await supabase.from("outfit_items").insert(links);
126	
127	  // Insert order is not guaranteed — place each id at its look's position.
128	  const ids: string[] = [];
129	  for (const row of inserted) ids[row.look_index - start] = row.id;
130	  return ids;
